package eval

func questDependenciesSuite() Suite {
	base := secretsAndCluesSuite()
	return Suite{ID: "064-quest-dependencies", Name: "Campaign Play 064: Quest Dependencies", Tests: append(base.Tests,
		playTest("play-quest-create-player-forbidden", "Players cannot create quests", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-player", "title": "Player quest", "depends_on": []any{}}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-quest-invalid-id", "Quest creation requires a nonempty quest ID", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "", "title": "Scout the cave", "depends_on": []any{}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-quest-invalid-title", "Quest creation requires a nonempty title", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-empty-title", "title": "", "depends_on": []any{}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-quest-unknown-dependency", "Quest dependencies must already exist", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-bad-dep", "title": "Find a shortcut", "depends_on": []any{"quest-missing"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-quest-self-dependency", "Quest cannot depend on itself", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-loop", "title": "Loop", "depends_on": []any{"quest-loop"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-quest-create-prerequisite", "DM creates prerequisite quest", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-scout", "title": "Scout the cave", "depends_on": []any{}}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"quest_id": "quest-scout", "title": "Scout the cave", "depends_on": []any{}, "state": "locked"}),
		playTest("play-quest-duplicate-dependency", "Quest dependencies must be unique", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-dup-dep", "title": "Find a shortcut", "depends_on": []any{"quest-scout", "quest-scout"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-quest-duplicate", "Duplicate quest IDs conflict", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-scout", "title": "Scout the cave", "depends_on": []any{}}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-quest-create-dependent", "DM creates dependent quest", "POST", "/v1/play/campaigns/play-2/quests", map[string]any{"quest_id": "quest-map", "title": "Map the tunnels", "depends_on": []any{"quest-scout"}}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"quest_id": "quest-map", "title": "Map the tunnels", "depends_on": []any{"quest-scout"}, "state": "locked"}),
		playTest("play-quest-state-player-forbidden", "Players cannot change quest state", "PUT", "/v1/play/campaigns/play-2/quests/quest-scout/state", map[string]any{"state": "active"}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-quest-state-unknown", "Unknown quest state change returns 404", "PUT", "/v1/play/campaigns/play-2/quests/quest-missing/state", map[string]any{"state": "active"}, map[string]string{"Authorization": dmAuth}, 404, nil),
		playTest("play-quest-state-invalid", "Quest state must be active or completed", "PUT", "/v1/play/campaigns/play-2/quests/quest-scout/state", map[string]any{"state": "paused"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-quest-dependent-blocked", "Dependent quest cannot activate before dependencies complete", "PUT", "/v1/play/campaigns/play-2/quests/quest-map/state", map[string]any{"state": "active"}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-quest-prerequisite-active", "DM activates prerequisite quest", "PUT", "/v1/play/campaigns/play-2/quests/quest-scout/state", map[string]any{"state": "active"}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"quest_id": "quest-scout", "title": "Scout the cave", "depends_on": []any{}, "state": "active"}),
		playTest("play-quest-active-active-conflict", "Quest cannot repeat the same active transition", "PUT", "/v1/play/campaigns/play-2/quests/quest-scout/state", map[string]any{"state": "active"}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-quest-prerequisite-completed", "DM completes prerequisite quest", "PUT", "/v1/play/campaigns/play-2/quests/quest-scout/state", map[string]any{"state": "completed"}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"quest_id": "quest-scout", "title": "Scout the cave", "depends_on": []any{}, "state": "completed"}),
		playTest("play-quest-locked-completed-conflict", "Locked quests cannot complete directly", "PUT", "/v1/play/campaigns/play-2/quests/quest-map/state", map[string]any{"state": "completed"}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-quest-dependent-active", "DM activates dependent quest after completion", "PUT", "/v1/play/campaigns/play-2/quests/quest-map/state", map[string]any{"state": "active"}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"quest_id": "quest-map", "title": "Map the tunnels", "depends_on": []any{"quest-scout"}, "state": "active"}),
		playTestExactJSON("play-quest-dependent-completed", "DM completes dependent quest", "PUT", "/v1/play/campaigns/play-2/quests/quest-map/state", map[string]any{"state": "completed"}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"quest_id": "quest-map", "title": "Map the tunnels", "depends_on": []any{"quest-scout"}, "state": "completed"}),
		playTestExactJSON("play-quest-read-state", "Campaign members read quests in creation order", "GET", "/v1/play/campaigns/play-2/quests", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"quests": []any{
			map[string]any{"quest_id": "quest-scout", "title": "Scout the cave", "depends_on": []any{}, "state": "completed"},
			map[string]any{"quest_id": "quest-map", "title": "Map the tunnels", "depends_on": []any{"quest-scout"}, "state": "completed"},
		}}),
	)}
}
